import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

/**
 * ApprovalRules with Datapills Example
 * Demonstrates: Using wfa.dataPill() and wfa.approvalDueDate() inside wfa.approvalRules()
 */

Flow(
    {
        $id: Now.ID['ask_for_approval_flow_example5'],
        name: 'ask-for-approval-due-date-with-action-reject-actual-date-example',
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['ask_for_approval_flow_example5_trigger'],
        },
        {
            table: 'incident',
            condition: '^EQ',
            run_on_extended: 'false',
            run_flow_in: 'any',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['ask_for_approval_flow_example5_ask_for_approval_action'],
            },
            {
                record: wfa.dataPill(_params.trigger.current, 'reference'),
                table: 'incident',
                approval_reason: 'Test reason 123',
                approval_field: 'approval',
                journal_field: 'approval_history',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: [wfa.dataPill(_params.trigger.current.assigned_to, 'reference')],
                                        groups: [wfa.dataPill(_params.trigger.current.assignment_group, 'reference')],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
                due_date: wfa.approvalDueDate({
                    action: 'reject',
                    dateType: 'actual',
                    date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time'),
                    duration: 1,
                    durationType: 'days',
                    daysSchedule: '',
                }),
            }
        )
    }
)
